 20:       CREATE TABLE IF NOT EXISTS chapters(work_id TEXT NOT NULL REFERENCES works(id), number INTEGER NOT NULL, revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,number)) STRICT;
